import { useState, useCallback } from 'react';

export interface FilingStatus {
  r1: boolean;
  r3b: boolean;
}

const STORAGE_KEY = 'clientify_monthly_filing_v3';

const getDynamicYears = () => {
  const startYear = 2023;
  const now = new Date();
  const currentYear = now.getFullYear();
  const currentMonth = now.getMonth(); // 0-11

  // In India, FY starts in April (index 3). 
  // If we are in April or later, the "Current" start year is the current calendar year.
  const latestStartYear = currentMonth >= 3 ? currentYear : currentYear - 1;

  const list = [];
  for (let y = startYear; y <= latestStartYear; y++) {
    list.push(`${y}-${(y + 1).toString().slice(-2)}`);
  }
  // Always include the next year if we are in the last quarter (Jan-Mar) to allow preparation
  if (currentMonth >= 0 && currentMonth <= 2 && !list.includes(`${currentYear}-${(currentYear + 1).toString().slice(-2)}`)) {
     // Optional: list.push(`${currentYear}-${(currentYear + 1).toString().slice(-2)}`);
  }

  return list.reverse(); // Latest years first
};

export const YEARS = getDynamicYears();

export const MONTHS = [
  'Full Year View',
  'April', 'May', 'June', 'July', 'August', 'September', 
  'October', 'November', 'December', 'January', 'February', 'March'
];

export const QUARTERS = [
  'Full Year View',
  'April-June (Q1)',
  'July-September (Q2)',
  'October-December (Q3)',
  'January-March (Q4)'
];

export const getDefaultPeriod = () => {
  const now = new Date();
  const m = now.getMonth();
  const calYear = now.getFullYear();

  const getFY = (month: number, year: number) => {
    if (month >= 3) return `${year}-${(year + 1).toString().slice(-2)}`;
    return `${year - 1}-${year.toString().slice(-2)}`;
  };

  let prevMonthIdx = m - 1;
  let mYear = calYear;
  if (prevMonthIdx < 0) {
    prevMonthIdx = 11;
    mYear = calYear - 1;
  }

  const monthFY = getFY(prevMonthIdx, mYear);

  let qIdx = 0;
  let qYear = calYear;
  if (m >= 0 && m <= 2) qIdx = 2;
  else if (m >= 3 && m <= 5) { qIdx = 3; qYear = calYear - 1; }
  else if (m >= 6 && m <= 8) qIdx = 0;
  else qIdx = 1;

  const qStartMonths = [3, 6, 9, 0];
  const quarterFY = getFY(qStartMonths[qIdx], qYear);

  // Note: MONTHS[0] is 'Full Year View', so indices are offset by 1
  return { 
    month: MONTHS[prevMonthIdx === 11 ? 12 : (prevMonthIdx < 3 ? prevMonthIdx + 10 : prevMonthIdx - 2)], 
    quarter: QUARTERS[qIdx + 1],
    year: monthFY,
    quarterYear: quarterFY
  };
};

export const useMonthlyFilingLogic = (selectedYear: string, selectedMonth: string) => {
  const [allData, setAllData] = useState<Record<string, Record<string, FilingStatus>>>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  });

  const toggleStatus = useCallback((clientId: string, type: 'r1' | 'r3b', specificMonth?: string) => {
    const targetMonth = specificMonth || selectedMonth;
    const periodKey = `${selectedYear}_${targetMonth}`;

    setAllData(prev => {
      const periodData = { ...(prev[periodKey] || {}) };
      const clientData = { ...(periodData[clientId] || { r1: false, r3b: false }) };
      clientData[type] = !clientData[type];
      periodData[clientId] = clientData;
      const next = { ...prev, [periodKey]: periodData };
      localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
      return next;
    });
  }, [selectedYear, selectedMonth]);

  const getStatus = useCallback((clientId: string, specificMonth?: string): FilingStatus => {
    const targetMonth = specificMonth || selectedMonth;
    const periodKey = `${selectedYear}_${targetMonth}`;
    return (allData[periodKey] || {})[clientId] || { r1: false, r3b: false };
  }, [allData, selectedYear, selectedMonth]);

  return { getStatus, toggleStatus };
};

